{
  "items": [
    {
      "name": "PowerSeries.coeff_subst'",
      "module_name": "Mathlib.RingTheory.PowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : CommRing R] {S : Type u_4} [inst_1 : CommRing S] [inst_2 : Algebra R S] {b : PowerSeries S},\n  PowerSeries.HasSubst b →\n    ∀ (f : PowerSeries R) (e : ℕ),\n      (PowerSeries.coeff e) (PowerSeries.subst b f) =\n        ∑ᶠ (d : ℕ), (PowerSeries.coeff d) f • (PowerSeries.coeff e) (b ^ d)"
    },
    {
      "name": "Polynomial.degreeLTEquiv",
      "module_name": "Mathlib.RingTheory.Polynomial.Basic",
      "kind": "definition",
      "type": "(R : Type u_2) → [inst : Semiring R] → (n : ℕ) → ↥(Polynomial.degreeLT R n) ≃ₗ[R] Fin n → R"
    },
    {
      "name": "PowerSeries.coeff_subst",
      "module_name": "Mathlib.RingTheory.PowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : CommRing R] {τ : Type u_3} {S : Type u_4} [inst_1 : CommRing S] [inst_2 : Algebra R S]\n  {a : MvPowerSeries τ S},\n  PowerSeries.HasSubst a →\n    ∀ (f : PowerSeries R) (e : τ →₀ ℕ),\n      (MvPowerSeries.coeff e) (PowerSeries.subst a f) =\n        ∑ᶠ (d : ℕ), (PowerSeries.coeff d) f • (MvPowerSeries.coeff e) (a ^ d)"
    },
    {
      "name": "Polynomial.coeff_expand",
      "module_name": "Mathlib.Algebra.Polynomial.Expand",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] {p : ℕ},\n  0 < p → ∀ (f : Polynomial R) (n : ℕ), ((Polynomial.expand R p) f).coeff n = if p ∣ n then f.coeff (n / p) else 0"
    },
    {
      "name": "Polynomial.sum_modByMonic_coeff",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] {p q : Polynomial R},\n  q.Monic → ∀ {n : ℕ}, q.degree ≤ ↑n → ∑ i, (Polynomial.monomial ↑i) ((p %ₘ q).coeff ↑i) = p %ₘ q"
    },
    {
      "name": "Polynomial.degreeLT",
      "module_name": "Mathlib.RingTheory.Polynomial.Basic",
      "kind": "definition",
      "type": "(R : Type u) → [inst : Semiring R] → ℕ → Submodule R (Polynomial R)"
    }
  ]
}

{
  "items": [
    {
      "name": "MvPowerSeries.coeff_subst",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S},\n  MvPowerSeries.HasSubst a →\n    ∀ (f : MvPowerSeries σ R) (e : τ →₀ ℕ),\n      (MvPowerSeries.coeff e) (MvPowerSeries.subst a f) =\n        ∑ᶠ (d : σ →₀ ℕ), (MvPowerSeries.coeff d) f • (MvPowerSeries.coeff e) (d.prod fun s e => a s ^ e)"
    },
    {
      "name": "MvPowerSeries.subst_monomial",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S},\n  MvPowerSeries.HasSubst a →\n    ∀ (e : σ →₀ ℕ) (r : R),\n      MvPowerSeries.subst a ((MvPowerSeries.monomial e) r) =\n        (algebraMap R (MvPowerSeries τ S)) r * e.prod fun s n => a s ^ n"
    },
    {
      "name": "MvPowerSeries.substAlgHom_monomial",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S} (ha : MvPowerSeries.HasSubst a) (e : σ →₀ ℕ) (r : R),\n  (MvPowerSeries.substAlgHom ha) ((MvPowerSeries.monomial e) r) =\n    (algebraMap R (MvPowerSeries τ S)) r * e.prod fun s n => a s ^ n"
    },
    {
      "name": "MvPolynomial.coeff_rename_embDomain",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_4} [inst : CommSemiring R] (f : σ ↪ τ) (φ : MvPolynomial σ R) (d : σ →₀ ℕ),\n  MvPolynomial.coeff (Finsupp.embDomain f d) ((MvPolynomial.rename ⇑f) φ) = MvPolynomial.coeff d φ"
    },
    {
      "name": "MvPowerSeries.constantCoeff_subst",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S},\n  MvPowerSeries.HasSubst a →\n    ∀ (f : MvPowerSeries σ R),\n      MvPowerSeries.constantCoeff (MvPowerSeries.subst a f) =\n        ∑ᶠ (d : σ →₀ ℕ), (MvPowerSeries.coeff d) f • MvPowerSeries.constantCoeff (d.prod fun s e => a s ^ e)"
    },
    {
      "name": "PowerSeries.coeff_subst",
      "module_name": "Mathlib.RingTheory.PowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : CommRing R] {τ : Type u_3} {S : Type u_4} [inst_1 : CommRing S] [inst_2 : Algebra R S]\n  {a : MvPowerSeries τ S},\n  PowerSeries.HasSubst a →\n    ∀ (f : PowerSeries R) (e : τ →₀ ℕ),\n      (MvPowerSeries.coeff e) (PowerSeries.subst a f) =\n        ∑ᶠ (d : ℕ), (PowerSeries.coeff d) f • (MvPowerSeries.coeff e) (a ^ d)"
    }
  ]
}

{
  "items": [
    {
      "name": "Finsupp.mapDomain_apply'",
      "module_name": "Mathlib.Data.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {M : Type u_5} [inst : AddCommMonoid M] (S : Set α) {f : α → β} (x : α →₀ M),\n  ↑x.support ⊆ S → Set.InjOn f S → ∀ {a : α}, a ∈ S → (Finsupp.mapDomain f x) (f a) = x a"
    },
    {
      "name": "Finsupp.mapDomain_injOn",
      "module_name": "Mathlib.Data.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {M : Type u_5} [inst : AddCommMonoid M] (S : Set α) {f : α → β},\n  Set.InjOn f S → Set.InjOn (Finsupp.mapDomain f) {w | ↑w.support ⊆ S}"
    },
    {
      "name": "Finsupp.mapDomain_injective",
      "module_name": "Mathlib.Data.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {M : Type u_5} [inst : AddCommMonoid M] {f : α → β},\n  Function.Injective f → Function.Injective (Finsupp.mapDomain f)"
    },
    {
      "name": "Finsupp.mapDomain_apply",
      "module_name": "Mathlib.Data.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {M : Type u_5} [inst : AddCommMonoid M] {f : α → β},\n  Function.Injective f → ∀ (x : α →₀ M) (a : α), (Finsupp.mapDomain f x) (f a) = x a"
    },
    {
      "name": "Finsupp.mapDomain_support_of_injOn",
      "module_name": "Mathlib.Data.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {M : Type u_5} [inst : AddCommMonoid M] [inst_1 : DecidableEq β] {f : α → β}\n  (s : α →₀ M), Set.InjOn f ↑s.support → (Finsupp.mapDomain f s).support = Finset.image f s.support"
    },
    {
      "name": "Finsupp.mapDomain",
      "module_name": "Mathlib.Data.Finsupp.Basic",
      "kind": "definition",
      "type": "{α : Type u_1} → {β : Type u_2} → {M : Type u_5} → [inst : AddCommMonoid M] → (α → β) → (α →₀ M) → β →₀ M"
    }
  ]
}
